package basispoints

import (
	"context"
	"fmt"
	"io"
)

// driveRepairFixture is a test application: replies are generated by each
// scenario, outside the converter. The production application driver is in
// service and is covered there through the real gateway send path.
func driveRepairFixture(ctx context.Context, bridge *Bridge, upstream io.ReadCloser,
	tool func(context.Context, object, error) (object, error),
	unknown func(context.Context) (io.ReadCloser, error),
) io.ReadCloser {
	ctx, cancel := context.WithCancel(ctx)
	reader, writer := io.Pipe()
	body := &streamBody{PipeReader: reader, upstream: upstream, cancel: cancel, done: make(chan struct{})}
	conversion := bridge.NewStreamConversion(writeSSEFixture(writer), RepairPolicy{ToolTransport: tool != nil, UnknownTarget: unknown != nil})
	go func() {
		defer close(body.done)
		defer cancel()
		stop := context.AfterFunc(ctx, func() {
			_ = writer.CloseWithError(ctx.Err())
			_ = body.closeUpstream()
		})
		defer stop()
		demand, err := conversion.Convert(upstream)
		for demand != nil && err == nil {
			_ = body.closeUpstream()
			var response object
			replyErr := ctx.Err()
			if replyErr == nil {
				switch demand.Kind {
				case RepairToolTransport, RepairUnknownContinuation:
					response, replyErr = tool(ctx, demand.FailedResponse, demand.Validation)
				case RepairUnknownTarget:
					var input io.ReadCloser
					input, replyErr = unknown(ctx)
					if replyErr == nil {
						stopRead := context.AfterFunc(ctx, func() { _ = input.Close() })
						response, replyErr = ReadRepairResponse(input, bridge.OnUpstreamEvent)
						stopRead()
						_ = input.Close()
					}
				}
			}
			if replyErr == nil {
				replyErr = ctx.Err()
			}
			demand, err = conversion.ResolveRepair(response, replyErr)
		}
		if err == nil {
			err = conversion.Deliver(bridge.CommitReplays(conversion.Replays()))
		}
		body.usage, body.failure = conversion.Usage(), conversion.Failure()
		body.cause = conversion.Cause()
		_ = body.closeUpstream()
		_ = writer.CloseWithError(err)
	}()
	return body
}

// writeSSEFixture serializes direct events for legacy wire assertions only.
func writeSSEFixture(writer io.Writer) func(string, []byte) error {
	return func(kind string, raw []byte) error {
		_, err := fmt.Fprintf(writer, "event: %s\ndata: %s\n\n", kind, raw)
		return err
	}
}
